# Generate scalene triangle sides with c < b < a and triangle inequality c + b > a
# Also generate a nontrivial homothety parameter k = k_num/k_den distinct from 1
import math
def gcd(x, y):
    while y:
        x, y = y, x % y
    return abs(x)
for _ in range(1000):
    c = rng.randint(5, 40)
    b = rng.randint(c + 1, 60)
    a = rng.randint(b + 1, 90)
    if b + c <= a:
        continue
    # Choose k in a range avoiding triviality
    k_den = rng.randint(2, 15)
    k_num_choices = [x for x in range(1, 25) if x != k_den]
    k_num = rng.choice(k_num_choices)
    if gcd(k_num, k_den) != 1:
        continue
    k = k_num / k_den
    if not (0.25 <= k <= 1.75):
        continue
    # Compute product via derived closed-form
    prod = abs(1 - k) ** 3 * abs((a - b) * (a - c) * (b - c)) / 8.0
    # Enforce nontrivial difficulty: not an integer, not tiny, and not a simple fraction like .5 or .25
    frac_part = abs(prod - round(prod))
    if prod < 5:
        continue
    if frac_part < 1e-9:
        continue
    # Avoid products whose fractional parts are very close to quarters to reduce trivial guessing
    qtest = min(abs(prod - round(prod * 4) / 4.0), abs(prod - round(prod * 8) / 8.0))
    if qtest < 1e-6:
        continue
    return {'a': a, 'b': b, 'c': c, 'k_num': k_num, 'k_den': k_den}
# Fallback deterministic generation if random fails
a, b, c = 50, 35, 21
k_num, k_den = 7, 5
return {'a': a, 'b': b, 'c': c, 'k_num': k_num, 'k_den': k_den}

